    test("retrieveArticleDraft (2)", async () => {
        const server = mockServerPool.createServer();
        const client = new IntercomClient({
            maxRetries: 0,
            token: "test",
            version: "2.14",
            environment: server.baseUrl,
        });

        const rawResponseBody = { type: "type", errors: [{ code: "code" }, { code: "code" }] };
        server.mockEndpoint().get("/articles/1/draft").respondWith().statusCode(401).jsonBody(rawResponseBody).build();

        await expect(async () => {
            return await client.preview.articles.retrieveArticleDraft({
                id: 1,
            });
        }).rejects.toThrow(Intercom.preview.UnauthorizedError);
    });

