    test("listVersions (1)", async () => {
        const server = mockServerPool.createServer();
        const client = new IntercomClient({
            maxRetries: 0,
            token: "test",
            version: "2.14",
            environment: server.baseUrl,
        });

        const rawResponseBody = {
            type: "list",
            pages: {
                type: "pages",
                page: 1,
                next: { per_page: 2, starting_after: "your-cursor-from-response" },
                per_page: 25,
                total_pages: 1,
            },
            total_count: 2,
            data: [
                {
                    type: "article_version",
                    id: "301",
                    article_id: "123",
                    title: "This is the article title",
                    description: "",
                    author_id: "991267502",
                    created_by_id: "5017691",
                    created_via: "web",
                    from_version_id: "300",
                    state: "published",
                    created_at: 1734537292,
                },
                {
                    type: "article_version",
                    id: "300",
                    article_id: "123",
                    title: "This was the earlier title",
                    description: "",
                    author_id: "991267502",
                    created_by_id: "5017691",
                    created_via: "api",
                    from_version_id: "300",
                    state: "draft",
                    created_at: 1734530000,
                },
            ],
        };
        server
            .mockEndpoint({ once: false })
            .get("/articles/1/versions")
            .respondWith()
            .statusCode(200)
            .jsonBody(rawResponseBody)
            .build();

        const expected = {
            type: "list",
            pages: {
                type: "pages",
                page: 1,
                next: {
                    per_page: 2,
                    starting_after: "your-cursor-from-response",
                },
                per_page: 25,
                total_pages: 1,
            },
            total_count: 2,
            data: [
                {
                    type: "article_version",
                    id: "301",
                    article_id: "123",
                    title: "This is the article title",
                    description: "",
                    author_id: "991267502",
                    created_by_id: "5017691",
                    created_via: "web",
                    from_version_id: "300",
                    state: "published",
                    created_at: 1734537292,
                },
                {
                    type: "article_version",
                    id: "300",
                    article_id: "123",
                    title: "This was the earlier title",
                    description: "",
                    author_id: "991267502",
                    created_by_id: "5017691",
                    created_via: "api",
                    from_version_id: "300",
                    state: "draft",
                    created_at: 1734530000,
                },
            ],
        };
        const page = await client.preview.articles.listVersions({
            article_id: 1,
            page: 1,
            per_page: 1,
            locale: "en",
        });

        expect(expected.data).toEqual(page.data);
        expect(page.hasNextPage()).toBe(true);
        const nextPage = await page.getNextPage();
        expect(expected.data).toEqual(nextPage.data);
    });

